function spanOf(ev,nat0){if(!MODN.has(nat0)||!ev.length)return null;const per=T=>T<1897.8?'조선':T<1910.66?'대한제국':T<1945.62?'일제강점기':(nat0==='한국'&&T<1948.6?'한국':'대한민국');const c={};ev.forEach(e=>{const p=per(e.T);c[p]=(c[p]||0)+1});const ks=Object.keys(c);if(ks.length<2)return null;const tot=ev.length;const ord=['조선','대한제국','일제강점기','한국','대한민국'];const keep=ord.filter(p=>c[p]&&c[p]/tot>=0.2);if(keep.length<2)return null;const prim=keep.slice().sort((a,b)=>c[b]-c[a]||ord.indexOf(b)-ord.indexOf(a))[0];return {nat:prim,tags:keep.map(p=>({t:p,nat:p}))}}
