  try{ME.n.forEach((v,k)=>{if(v==='p'&&!o[k]&&!kingOfName(k)&&!ALK(k))add(k,{d:GLOSS[k]||PINFO[k]||'',nat:ov(k)||'기타',T:9999})})}catch(_){}
  /* 왕: 이름만(괄호 나라 없이), "조선 26대 왕"처럼 번호, 조선→대한제국 걸친 고종은 하나로 */
  const yr=v=>{const y=Math.floor(v);return y<0?'기원전 '+(-y):String(y)};const KM=new Map();
