    const pres=D.n==='남한'||D.n==='북한';const role=pres?(D.n==='남한'?'대통령':'지도자'):D.n==='대한제국'?`${i+1}대 황제`:`${i+1}대 왕`;const tag=pres?`${dn} ${role}`:`${dn} ${role}`;
    const mk=D.n==='대한제국'&&KM.has('조선|'+base)?'조선|'+base:D.n+'|'+base+'|'+i;
